# =========================================================== factory: तथ्य और राय

def fact_opinion(t, frames, mode='read'):
    """frames need 'fo' = [(statement, 'तथ्य' | 'राय', why)]."""

    def pick(r):
        P = frame_of(r, frames, mode)
        if not P or not P.get('fo'):
            return None, [], []
        F = [x for x in P['fo'] if x[1] == 'तथ्य']
        O = [x for x in P['fo'] if x[1] == 'राय']
        return P, F, O

    @t.add('C1', (1, 2, 3))
    def fo_c1(r, D):
        P, F, O = pick(r)
        if not P:
            return None
        if r.random() < 0.5 and len(O) >= 1 and len(F) >= 3:
            g = r.choice(O)
            return mq(r, head(P) + 'इनमें से कौन-सा कथन लेखक की राय है, तथ्य नहीं?', g[0], [x[0] for x in r.sample(F, 3)], g[2])
        if len(F) >= 1 and len(O) >= 3:
            g = r.choice(F)
            return mq(r, head(P) + 'इनमें से कौन-सा कथन तथ्य है, जिसे जाँचा या प्रमाणित किया जा सकता है?', g[0], [x[0] for x in r.sample(O, 3)], g[2])
        return None

    @t.add('C2', (1, 2, 3, 4), 'explain')
    def fo_c2(r, D):
        P, F, O = pick(r)
        if not P:
            return None
        m = mk('C2', D)
        st, lab, why = r.choice(P['fo'])
        stem = head(P) + f'कथन {Q(st)} तथ्य है या राय? ' + ('अपने उत्तर का कारण दीजिए।' if m >= 2 else 'उत्तर संक्षेप में दीजिए।')
        return item(stem, f'{lab}। {why}', f'{lab} (1)' + ('; कारण — ' + why + ' (1)' if m >= 2 else '') + (' ; पहचान के संकेत (जैसे “मेरे विचार से”, आँकड़े, स्रोत) का उल्लेख (1)' if m >= 3 else ''), m, 'explain')

    @t.add('C3', (1, 2, 3, 4, 5), 'short')
    def fo_c3(r, D):
        P, F, O = pick(r)
        if not P or len(P['fo']) < 3:
            return None
        parts = [(f'कथन {Q(s)} — तथ्य या राय?', lab, f'{lab} [1]') for s, lab, why in P['fo']]
        parts.append(('लेख में से राय प्रकट करने वाला कोई एक शब्द या वाक्यांश लिखिए।', P.get('cue', 'मेरे विचार से / मुझे लगता है'), 'राय-सूचक कोई उपयुक्त शब्द/वाक्यांश [1]'))
        return hcompose(r, head(P) + 'नीचे दिए गए कथनों को पढ़कर उत्तर दीजिए।', parts, k=(2, 3, 4))

    @t.add('C4', (2, 3, 4, 5), 'multi_step')
    def fo_c4(r, D):
        P, F, O = pick(r)
        if not P or not F or not O:
            return None
        m = mk('C4', D)
        stem = head(P) + r.choice(['इस पाठ से दो तथ्य और दो राय छाँटिए। फिर बताइए कि लेखक ने अपनी राय को प्रभावशाली बनाने के लिए तथ्यों का प्रयोग कैसे किया है।',
                                   'लेखक तथ्य और राय को कैसे मिलाता है? पाठ से उदाहरण देकर समझाइए और बताइए कि पाठक को ऐसे लेख पढ़ते समय क्या सावधानी रखनी चाहिए।'])
        ans = 'तथ्य: ' + '; '.join(x[0] for x in F[:2]) + ' राय: ' + '; '.join(x[0] for x in O[:2]) + ' ' + P.get('fo_use', 'लेखक तथ्यों से अपनी राय को विश्वसनीय बनाता है; पाठक को राय को तथ्य से अलग पहचानना चाहिए।')
        key = f'दो सही तथ्य और दो सही राय (प्रत्येक 0.5, कुल 2); तथ्यों के प्रयोग की व्याख्या (1); पाठक के लिए सावधानी/मूल्यांकन (शेष अंक, कुल {m})'
        return item(stem, ans, key, m, 'multi_step')


# =========================================================== factory: भ्रामक विकल्प (श्रवण)

def traps(t, frames, mode='listen'):
    """frames need 'traps' = [(question, correct, trap, why)] — the trap is mentioned in the transcript but is wrong."""

    def pick(r):
        P = frame_of(r, frames, mode)
        return (P, r.choice(P['traps'])) if P and P.get('traps') else (None, None)

    @t.add('C1', (1, 2, 3))
    def tr_c1(r, D):
        P, x = pick(r)
        if not P:
            return None
        q, a, tr, why = x
        pool = [y[2] for y in P['traps'] if y[2] != tr and y[2] != a] + [y[1] for y in P['traps'] if y[1] != a and y[1] != tr]
        if len(pool) < 2:
            return None
        return mq(r, head(P) + q, a, [tr] + r.sample(pool, 2), f'{Q(tr)} प्रतिलेख में आता है, पर {why}')

    @t.add('C2', (1, 2, 3, 4), 'explain')
    def tr_c2(r, D):
        P, x = pick(r)
        if not P:
            return None
        q, a, tr, why = x
        m = mk('C2', D)
        n, g = name(r)
        stem = head(P) + f'प्रश्न: {q}\n{n} ने उत्तर चुना: {Q(tr)}। यह विकल्प भ्रामक क्यों है? ' + ('सही उत्तर भी लिखिए।' if m >= 2 else 'उत्तर संक्षेप में दीजिए।')
        return item(stem, f'{why} सही उत्तर: {a}।', 'भ्रामक होने का कारण (1)' + ('; सही उत्तर (1)' if m >= 2 else '') + ('; प्रतिलेख से प्रमाण (1)' if m >= 3 else ''), m, 'explain')

    @t.add('C3', (1, 2, 3, 4, 5), 'short')
    def tr_c3(r, D):
        P = frame_of(r, frames, mode)
        if not P or not P.get('traps'):
            return None
        parts = [(q, a, f'{a} [1]') for q, a, tr, why in P['traps']]
        parts.append(('इस बातचीत से कोई एक भ्रामक विकल्प (पहले कही गई पर बाद में बदली गई जानकारी) लिखिए और बताइए कि वह गलत क्यों है।', '; '.join(f'{tr} — {why}' for q, a, tr, why in P['traps']), 'उपयुक्त भ्रामक विकल्प (1); कारण (1) [2]'))
        lead = r.choice(['प्रतिलेख ध्यान से पढ़कर उत्तर दीजिए। ध्यान रखें: बातचीत में आए हर शब्द का उत्तर होना ज़रूरी नहीं।',
                         'नीचे दिए गए प्रश्नों के उत्तर लिखिए। सावधान: वक्ता कुछ बातें बाद में बदल देते हैं, इसलिए अंतिम निर्णय पर ध्यान दीजिए।',
                         'श्रवण-अभ्यास: प्रत्येक प्रश्न का सही उत्तर लिखिए और पहले कही गई पर बाद में बदली गई जानकारी से बचिए।'])
        return hcompose(r, head(P) + lead, parts, k=(2, 3, 4))

    @t.add('C4', (2, 3, 4, 5), 'multi_step')
    def tr_c4(r, D):
        P = frame_of(r, frames, mode)
        if not P or not P.get('traps'):
            return None
        m = mk('C4', D)
        stem = head(P) + 'इस प्रतिलेख में वक्ता कई बार अपनी बात बदलते या सुधारते हैं। ऐसे दो स्थान पहचानिए, बताइए कि परीक्षा में कौन-से विकल्प भ्रामक हो सकते हैं, और ऐसे प्रश्नों के लिए अपनी रणनीति लिखिए।'
        ans = ' '.join(f'{q} — सही: {a}; भ्रामक: {tr} ({why})' for q, a, tr, why in P['traps'][:3]) + ' रणनीति: अंतिम निर्णय तक सुनें; “नहीं, बल्कि”, “पहले… पर अब” जैसे संकेत पहचानें; दूसरी बार सुनते समय उत्तर जाँचें।'
        key = f'दो सही स्थान और भ्रामक विकल्प (प्रत्येक 1, कुल 2); कारण की व्याख्या (1); व्यावहारिक रणनीति (शेष अंक, कुल {m})'
        return item(stem, ans, key, m, 'multi_step')


