              vocab=[('सन्नाटा', 'पूरी तरह चुप्पी', ['शोर', 'हँसी', 'झगड़ा']), ('पीढ़ी', 'एक ही समय में जन्मे लोगों का समूह', ['परिवार का घर', 'पुराना ज़माना', 'रिश्तेदार'])],
              tf=[('लेखिका के अनुसार सम्मान का अर्थ चुप रहना है।', False, 'वह कहती है कि सम्मान का अर्थ चुप रहना नहीं है।'), ('दादी भी युवावस्था में गाना चाहती थीं।', True, 'दादी ने स्वयं यह बताया।')],
