def reg_task(r):
    n, g = name(r)
    formal = f'मॉडल (औपचारिक): “आदरणीय महोदय/महोदया, … सविनय निवेदन है कि … आशा है आप … पर विचार करेंगे। सधन्यवाद, भवदीय/भवदीया {n}”'
    informal = f'मॉडल (अनौपचारिक): “प्रिय …, कैसे हो? … मुझे याद है जब मैं … तुम चिंता मत करो … ढेर सारा प्यार, तुम्हारा/तुम्हारी {n}”'
    top = r.choice([
        ('आपके विद्यालय ने अगले महीने एक “करियर मेला” आयोजित करने का निर्णय लिया है। (क) अपने मित्र को अनौपचारिक ई-मेल लिखकर इसमें साथ चलने का निमंत्रण दीजिए; या (ख) आयोजक को औपचारिक ई-मेल लिखकर स्वयंसेवक बनने की इच्छा प्रकट कीजिए।', ['मेले की जानकारी', 'आपकी रुचि का कारण', 'आप क्या करेंगे', 'उचित समापन'], formal + '; ' + informal),
        ('आपके मोहल्ले के पुस्तकालय ने शाम को बंद होने का समय घटा दिया है। पुस्तकालय-प्रबंधक को एक औपचारिक ई-मेल लिखिए।', ['समस्या का विवरण', 'विद्यार्थियों पर प्रभाव', 'आपका सुझाव', 'विनम्र अनुरोध'], formal),
        ('आपके चचेरे भाई ने नया विद्यालय शुरू किया है और वह उदास है। उसे एक अनौपचारिक ई-मेल लिखिए।', ['उसकी भावनाओं को समझना', 'अपना ऐसा ही अनुभव', 'नए दोस्त बनाने के सुझाव', 'प्रोत्साहन'], informal),
    ])
    return {'task': top[0], 'bullets': top[1], 'ind': 'पाठक के अनुसार सही शैली (औपचारिक/अनौपचारिक) का सतत प्रयोग; उचित संबोधन, विषय और समापन; सभी बिंदु विस्तार से; शब्द-चयन शैली के अनुरूप।',
            'model': top[2]}


