def srep_task(r):
    sp = r.choice(['फ़ुटबॉल', 'कबड्डी', 'बास्केटबॉल', 'खो-खो', 'हॉकी', 'वॉलीबॉल'])
    top = r.choice([
        (f'आपके विद्यालय ने ज़िला-स्तरीय {sp} प्रतियोगिता में भाग लिया। स्कूल पत्रिका के लिए इस प्रतियोगिता की रिपोर्ट लिखिए।', ['प्रतियोगिता कब, कहाँ और किनके बीच हुई', 'मुख्य मैच के रोमांचक क्षण', 'किसी खिलाड़ी या कोच की प्रतिक्रिया', 'परिणाम और पुरस्कार']),
        ('आपके विद्यालय में वार्षिक खेल-दिवस मनाया गया। स्थानीय अख़बार के लिए इसकी रिपोर्ट लिखिए।', ['आयोजन की तिथि, स्थान और मुख्य अतिथि', 'प्रमुख प्रतियोगिताएँ और विजेता', 'कोई विशेष या अनोखा क्षण', 'समापन और पुरस्कार-वितरण']),
    ])
    first = (f'मॉडल: “{sp} में हमारे विद्यालय का परचम” — 18 जनवरी को ज़िला खेल-परिसर में आयोजित ज़िला-स्तरीय {sp} प्रतियोगिता में आठ विद्यालयों की टीमों ने भाग लिया, जिसमें हमारी टीम ने फ़ाइनल जीतकर ट्रॉफ़ी अपने नाम की।'
             if 'ज़िला-स्तरीय' in top[0] else 'मॉडल: “उत्साह और खेल-भावना का दिन” — 5 दिसंबर को विद्यालय के मैदान में वार्षिक खेल-दिवस मनाया गया, जिसके मुख्य अतिथि ज़िला खेल-अधिकारी थे; दिन भर में बीस से अधिक प्रतियोगिताएँ हुईं।')
    return {'task': top[0], 'bullets': top[1], 'ind': 'स्पष्ट शीर्षक; आरंभ में मूल तथ्य; घटनाओं का क्रमबद्ध, भूतकाल में वर्णन; नाम, स्कोर, समय; किसी का कथन; निष्पक्ष, औपचारिक भाषा; परिणाम सहित समापन।',
            'model': 'मॉडल: शीर्षक — “… में हमारे विद्यालय की शानदार जीत”; आरंभ — तिथि, स्थान, टीमें; मध्य — मुख्य क्षण, स्कोर, खिलाड़ी; कथन — कप्तान/कोच; अंत — पुरस्कार और संदेश।', 'first': first}


def srep_short(r, D):
    T = srep_task(r)
    return (f'{T["task"]}\nइस रिपोर्ट का शीर्षक और पहला अनुच्छेद (लगभग 40 शब्द) लिखिए।', T['first'], 'परिणाम बताने वाला शीर्षक (1); क्या, कब, कहाँ, कौन — मूल तथ्य (1); भाषा')


