def cmp_task(r):
    item_ = r.choice([('मिक्सर', 'पहली बार चलाते ही वह बंद हो गया', 'ा'), ('स्कूल-बैग', 'एक सप्ताह में ही उसकी ज़िप टूट गई', 'ा'), ('स्मार्ट-घड़ी', 'उसकी बैटरी दो घंटे भी नहीं चलती', 'ी'), ('किताबों का सेट', 'उसमें दो किताबें गलत भेजी गईं', 'ा')])
    top = r.choice([
        (f'आपने एक ऑनलाइन दुकान से {item_[0]} मँगवा{item_[2]}, पर {item_[1]}। कंपनी के ग्राहक-सेवा विभाग को एक शिकायती ई-मेल लिखिए।', ['आपने क्या और कब खरीदा', 'समस्या का विवरण', 'इससे आपको क्या असुविधा हुई', 'आप क्या समाधान चाहते हैं']),
        ('आपने एक रेस्तराँ से खाना मँगवाया, जो डेढ़ घंटे देर से और ठंडा पहुँचा, और एक व्यंजन भी गलत था। रेस्तराँ-प्रबंधक को शिकायती ई-मेल लिखिए।', ['ऑर्डर का विवरण', 'क्या-क्या गलत हुआ', 'ग्राहक-सेवा का व्यवहार', 'आपकी माँग']),
    ])
    return {'task': top[0], 'bullets': top[1], 'ind': 'औपचारिक प्रारूप (विषय, संबोधन, समापन); तिथि, ऑर्डर संख्या, समस्या का तथ्यात्मक विवरण; विनम्र पर दृढ़ स्वर; स्पष्ट माँग और समय-सीमा; संलग्न प्रमाण।',
            'model': 'मॉडल: विषय — ऑर्डर संख्या … — खराब … के संबंध में शिकायत; आदरणीय महोदय, … को मैंने … मँगवाया … खेद है कि … इससे … असुविधा हुई … अतः अनुरोध है कि सात दिनों में … सधन्यवाद, भवदीय … संलग्न: रसीद, तस्वीर।'}


